package com.bananalab.lite;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;
/** One immutable result snapshot with its own local preview. */
final class BananaSceneCard extends LinearLayout{
 interface Host extends BananaEditor.Host{void export(String kind,SceneDraft snapshot);void restore(SceneDraft snapshot);void timeline(SceneDraft snapshot);void research(SceneDraft snapshot);void environment(SceneDraft snapshot);void activate(BananaSceneCard card);void failed(String text);}
 final SceneDraft snapshot;final boolean draft;private final Activity activity;private final Host host;private final TextView status;private final LinearLayout panel;private final Surface surface;private Scene scene;private Motion motion;private final Handler timer=new Handler(Looper.getMainLooper());private final PreviewSound sound=new PreviewSound();private Thread loader;private boolean dead,playing,foreground=true,playWhenReady;private int frame;private float time;private long started;
 BananaSceneCard(Activity a,SceneDraft value,boolean pending,Host h)throws Exception{super(a);activity=a;host=h;snapshot=value.copy();draft=pending;setOrientation(1);setPadding(12,12,12,12);setBackgroundColor(0xff263341);TextView title=new TextView(a);title.setText(!BananaProject.same(snapshot,BananaProject.current(a))?"Versión anterior":pending?"Borrador · sin publicar":"Resultado de Banana");title.setTextColor(0xfff6cf66);title.setTextSize(16);addView(title);status=new TextView(a);status.setTextColor(Color.WHITE);addView(status);surface=new Surface(a);addView(surface,new LinearLayout.LayoutParams(-1,Math.round(220*a.getResources().getDisplayMetrics().density)));LinearLayout row=new LinearLayout(a);addView(row);button(row,"Reproducir",()->prepare(true));button(row,"Editar",()->edit(snapshot.focused));button(row,"Guardar",()->saveMenu());LinearLayout second=new LinearLayout(a);addView(second);button(second,"Ver plan",()->{try{UiTypeface.show(new AlertDialog.Builder(a).setTitle("Plan del resultado").setMessage(SceneAudit.report(snapshot)).setPositiveButton("Cerrar",null));}catch(Exception e){host.failed(e.getMessage());}});button(second,"Más",()->more());panel=new LinearLayout(a);panel.setOrientation(1);addView(panel);status.setText(snapshot.cast.size()+" personajes · "+snapshot.actions.size()+" acciones");}
 private void button(LinearLayout row,String text,Runnable action){Button b=new Button(activity);b.setText(text);b.setAllCaps(false);row.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setOnClickListener(v->{if(!host.locked())action.run();});}
 void edit(String actor){try{if(!BananaProject.same(snapshot,BananaProject.current(activity))){UiTypeface.show(new AlertDialog.Builder(activity).setTitle("Resultado anterior").setMessage("Para editarlo, retomá esta versión como proyecto actual.").setPositiveButton("Retomar",(d,w)->host.restore(snapshot)).setNegativeButton("Cancelar",null));return;}stop();panel.removeAllViews();if(snapshot.cast.isEmpty()){status.setText("Agregá un personaje desde la conversación para editarlo.");return;}panel.addView(new BananaEditor(activity,snapshot,actor,host));panel.post(()->panel.requestRectangleOnScreen(new Rect(0,0,panel.getWidth(),Math.min(panel.getHeight(),Math.round(180*activity.getResources().getDisplayMetrics().density))),false));}catch(Exception e){host.failed(e.getMessage());}}
 private void saveMenu(){if(draft){status.setText("Publicá el borrador desde la conversación antes de guardarlo como resultado.");return;}UiTypeface.show(new AlertDialog.Builder(activity).setTitle("Guardar este resultado").setItems(new String[]{"Imagen PNG","GIF","Vídeo MP4","Escena en mi serie"},(d,i)->{if(i<3)host.export(new String[]{"png","gif","mp4"}[i],snapshot);else{EditText name=new EditText(activity);name.setHint("Nombre de la escena");UiTypeface.show(new AlertDialog.Builder(activity).setTitle("Guardar escena").setView(name).setPositiveButton("Guardar",(dd,w)->{try{SceneLibrary.save(activity,name.getText().toString(),snapshot);status.setText("Escena guardada en tu serie.");}catch(Exception e){host.failed(e.getMessage());}}).setNegativeButton("Cancelar",null));}}));}
 private void more(){UiTypeface.show(new AlertDialog.Builder(activity).setTitle("Este resultado").setItems(new String[]{"Editar secuencia","Retomar esta versión","Pausar","Buscar referencias","Ambiente"},(d,i)->{if(i==0)host.timeline(snapshot);else if(i==1)host.restore(snapshot);else if(i==2)stop();else if(i==3)host.research(snapshot);else host.environment(snapshot);}));}
 void prepare(boolean auto){if(dead)return;host.activate(this);stop();playWhenReady=auto&&foreground;if(loader!=null&&loader.isAlive()){status.setText("Preparando este resultado…");return;}if(scene!=null){if(playWhenReady){playWhenReady=false;play();}return;}status.setText("Preparando dibujo y animación…");loader=new Thread(()->{try{Motion m=Learning.load(activity);Scene next=BananaRender.prepare(activity.getApplicationContext(),snapshot,activity.getSharedPreferences("cinema",0).getBoolean("three",false));if(!dead)activity.runOnUiThread(()->{if(dead)return;motion=m;scene=next;time=0;status.setText("Resultado listo · "+snapshot.cast.size()+" personajes · "+snapshot.actions.size()+" acciones");surface.invalidate();if(playWhenReady&&foreground&&!snapshot.actions.isEmpty()){playWhenReady=false;play();}});}catch(Exception|OutOfMemoryError e){if(!dead)activity.runOnUiThread(()->{if(!dead)status.setText("No se generó: "+e.getMessage());});}},"banana-result-preview");loader.start();}
 private void play(){stop();playing=true;frame=0;sound.play(snapshot,scene.frames());started=android.os.SystemClock.uptimeMillis();timer.post(tick);}
 private final Runnable tick=new Runnable(){public void run(){if(dead||!playing||scene==null)return;long audio=sound.elapsedMillis(),elapsed=audio>=0?audio:android.os.SystemClock.uptimeMillis()-started;float duration=scene.frames()*1000f/VideoExporter.FPS;time=Math.max(0,Math.min(1,elapsed/duration));frame=Math.min(scene.frames()-1,(int)(elapsed*VideoExporter.FPS/1000));surface.invalidate();if(elapsed>=duration){playing=false;sound.stop();status.setText("Resultado listo · "+snapshot.cast.size()+" personajes · "+snapshot.actions.size()+" acciones");}else timer.postDelayed(this,32);}};
 float stillTime(){return time;}
 void setForeground(boolean value){foreground=value;if(!value)stop();}
 void stop(){playWhenReady=false;playing=false;timer.removeCallbacks(tick);sound.stop();}
 void close(){dead=true;stop();if(loader!=null)loader.interrupt();surface.release();}
 private final class Surface extends View{private Bitmap buffer;private Canvas target;private final Paint paint=new Paint(Paint.FILTER_BITMAP_FLAG);Surface(Context c){super(c);setContentDescription("Vista del resultado de Banana");}protected void onDraw(Canvas canvas){super.onDraw(canvas);int side=Math.min(getWidth(),getHeight()),n=Math.min(384,side);if(n<1)return;canvas.drawColor(0xff1b2631);if(scene==null)return;try{if(buffer==null||buffer.getWidth()!=n){release();buffer=Bitmap.createBitmap(n,n,Bitmap.Config.ARGB_8888);target=new Canvas(buffer);}buffer.eraseColor(Color.TRANSPARENT);scene.draw(target,n,motion,time);float x=(getWidth()-side)/2f,y=(getHeight()-side)/2f;canvas.drawBitmap(buffer,null,new RectF(x,y,x+side,y+side),paint);}catch(Throwable e){stop();status.setText("No se pudo mostrar este resultado.");}}void release(){if(buffer!=null)buffer.recycle();buffer=null;target=null;}}
}
